figure.artwork:
PPN {
  Path ID (32),
  Zeroes (2) = 0b00,
  Packet Number (62)
}

PATH_ABANDON Frame {
  Type (i) = 0x3e75,
  Path Identifier (i),
  Error Code (i),
}

PATH_STATUS_AVAILABLE Frame {
  Type (i) = 0x3e77,
  Path Identifier (i),
  Path Status Sequence Number (i),
}

PATH_STATUS_BACKUP Frame {
  Type (i) = 0x3e76
  Path Identifier (i),
  Path Status Sequence Number (i),
}

PATH_RETIRE_CONNECTION_ID Frame {
  Type (i) = 0x3e79,
  Path Identifier (i),
  Sequence Number (i),
}

MAX_PATH_ID Frame {
  Type (i) = 0x3e7a,
  Maximum Path Identifier (i),
}

PATHS_BLOCKED Frame {
  Type (i) = 0x3e7b,
  Maximum Path Identifier (i),
}

PATH_CIDS_BLOCKED Frame {
  Type (i) = 0x3e7c,
  Path Identifier (i),
  Next Sequence Number (i),
}
